"use client"

/**
 * The dashboard's hero number — clients with documents still outstanding —
 * remixable by Vendo (06-apps §8).
 *
 * Deliberately self-contained (React only, inline styles) so `vendo sync`
 * static capture reproduces it faithfully inside the sandboxed jail, whose
 * module space is React plus captured sub-sources and whose CSS is the
 * captured app-root stylesheet, not the compiled Tailwind bundle. The values
 * mirror the Cadence brand tokens in `src/app/globals.css`.
 */

const INK = "#111111"
const INK_SOFT = "#46443f"
const INK_FAINT = "#908c85"
const LINE = "#ecebe8"
const LEDGER_GREEN = "#1e7f53"
const STATUS_MISSING = "#a16207"
const STATUS_MISSING_BG = "#faf3e3"
const FONT = 'var(--font-inter, system-ui), ui-sans-serif, system-ui, sans-serif'

export interface MissingDocsHeroProps {
  /** Clients with at least one outstanding (missing/rejected) document. */
  missingCount: number
  /** All active clients. */
  clientCount: number
  badgeLabel?: string
  /** Week-over-week change: positive means more clients missing docs than last week. */
  weekOverWeekDelta?: number
}

export function MissingDocsHero({
  missingCount,
  clientCount,
  badgeLabel = "Action needed",
  weekOverWeekDelta,
}: MissingDocsHeroProps) {
  // Derive the week-over-week label and color only when a delta is provided.
  const hasDelta = typeof weekOverWeekDelta === "number"
  const deltaAbs = hasDelta ? Math.abs(weekOverWeekDelta as number) : 0
  const deltaImproved = hasDelta && (weekOverWeekDelta as number) < 0
  const deltaWorse = hasDelta && (weekOverWeekDelta as number) > 0
  const deltaFlat = hasDelta && (weekOverWeekDelta as number) === 0

  // Color: fewer missing docs (negative delta) is good — use ledger green.
  // More missing docs (positive delta) is a concern — use the danger tone.
  const deltaColor = deltaImproved
    ? LEDGER_GREEN
    : deltaWorse
    ? "#b0473a"
    : INK_FAINT

  const deltaLabel = deltaFlat
    ? "No change from last week"
    : deltaImproved
    ? `${deltaAbs} fewer than last week`
    : `${deltaAbs} more than last week`

  return (
    <article
      style={{
        borderRadius: 12,
        border: `1px solid ${LINE}`,
        background: "#ffffff",
        boxShadow: `inset 3px 0 0 ${LEDGER_GREEN}, 0 1px 2px rgba(17,17,17,0.04)`,
        padding: 20,
        fontFamily: FONT,
      }}
    >
      <p
        style={{
          margin: 0,
          fontSize: 13,
          fontWeight: 500,
          whiteSpace: "nowrap",
          color: INK_SOFT,
        }}
      >
        Clients missing documents
      </p>
      <div
        style={{
          marginTop: 12,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: 12,
        }}
      >
        <span
          style={{
            fontSize: 40,
            lineHeight: 1,
            fontWeight: 600,
            letterSpacing: "-0.025em",
            color: INK,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {missingCount}
        </span>
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 6,
            borderRadius: 9999,
            padding: "2px 8px",
            fontSize: 11,
            fontWeight: 500,
            whiteSpace: "nowrap",
            background: STATUS_MISSING_BG,
            color: STATUS_MISSING,
          }}
        >
          <span
            aria-hidden
            style={{
              width: 6,
              height: 6,
              borderRadius: 9999,
              background: "currentcolor",
            }}
          />
          {badgeLabel}
        </span>
      </div>
      <p
        style={{
          margin: "10px 0 0",
          fontSize: 12,
          color: INK_FAINT,
        }}
      >
        of {clientCount} active clients need chasing
      </p>
      {hasDelta && (
        <p
          style={{
            margin: "6px 0 0",
            fontSize: 12,
            color: deltaColor,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {deltaLabel}
        </p>
      )}
    </article>
  )
}

// <Remixable> derives its remix slot from this identity at runtime, and the
// production bundle minifies the function name away — displayName is the
// React-canonical identity that survives, matching the exported identifier
// sync captures the baseline under.
MissingDocsHero.displayName = "MissingDocsHero"

// The jail's module loader renders a fork's DEFAULT export (08-ui §5), so a
// remixable component must carry one; the named export stays for host imports.
export default MissingDocsHero
